#!/bin/bash
# scAnt Setup for macOS (Apple Silicon) and Ubuntu (x86-64): the installer itself.
#
# It runs from the folder the self-extracting scAnt-Setup-<version>-<platform>.sh unpacks (see stub.sh), which
# holds pins.sh (generated by build_installer.sh from manifest-<platform>.json), app/ (the app tree, pruned, with
# rig_stack's library), payloads/ (env-lock, focus-stack, shinestacker, on macOS ffmpeg-spinvideo), launcher/ and
# third_party/. Run the downloaded file, not this script:
#
#   bash scAnt-Setup-<version>-<platform>.sh [options]       (--help lists them)
#
# Installs per user, without administrator rights (Ubuntu's optional system setup asks for sudo):
#   macOS:  ~/Library/scAnt        and the app ~/Applications/scAnt.app
#   Ubuntu: ~/.local/share/scAnt   and a menu entry (~/.local/share/applications/scant.desktop)
# Layout: app/ (the scAnt tree), env/ (Python, micromamba-created from the lock), bin/ (launcher, checks),
# tools/ (Ubuntu: COLMAP's own env), flir/ (macOS: the Spinnaker runtime unpacked from the customer's pkg),
# payload-cache/, third_party_licenses/, install.json, install.log, install-smoke.log, uninstall.sh.
#
# Written for bash 3.2 (macOS's /bin/bash).

set -euo pipefail

SRC="$(cd "$(dirname "$0")" && pwd -P)"
# shellcheck source=/dev/null
. "$SRC/pins.sh"

# ---------------------------------------------------------------------------------------------------------------
# options
# ---------------------------------------------------------------------------------------------------------------

usage() {
    cat <<EOF
scAnt Setup $SCANT_VERSION ($SCANT_PLATFORM_TITLE)

  bash $(basename "${SCANT_SETUP_FILE:-scAnt-Setup.sh}") [options]

Options:
  --prefix DIR          install folder (default: $(default_prefix)); no spaces allowed
  --components LIST     comma-separated, from: flir,colmap,brush (core is always installed;
                        default: colmap,brush, plus flir when its files are given or found)
  --no-flir, --no-colmap, --no-brush
                        leave that component out
EOF
    if [ "$SCANT_OS" = macos ]; then cat <<EOF
  --flir-pkg FILE       Teledyne's Spinnaker SDK for macOS: $FLIR_PKG_NAME (or the .dmg that holds it)
EOF
    else cat <<EOF
  --flir-sdk FILE       Teledyne's Spinnaker SDK for your Ubuntu: $FLIR_SDK_JAMMY_NAME
                        or $FLIR_SDK_NOBLE_NAME (only if the SDK is not installed yet)
  --flir-python FILE    Teledyne's $FLIR_PY_NAME
  --colmap cpu|cuda|auto  which COLMAP build (default auto: CUDA when an NVIDIA driver for CUDA 12.9 is present)
  --system-setup        run the steps that need sudo (serial port access, ModemManager, FLIR SDK) without asking
  --no-system-setup     skip them (they are printed instead)
EOF
    fi
    cat <<EOF
  --accept-flir-license accept the FLIR Spinnaker SDK License Agreement without showing it (silent installs)
  --yes                 answer every question with its default (no prompts)
  --no-launcher         do not create the app launcher / menu entry
  --repair              re-create the Python environment even if it is up to date
  --uninstall           remove an installation (run it from the install folder: uninstall.sh)
  -h, --help            this help
EOF
}

case "$SCANT_PLATFORM" in
    macos-arm64) SCANT_OS=macos; SCANT_PLATFORM_TITLE="macOS, Apple Silicon" ;;
    linux-x86_64) SCANT_OS=linux; SCANT_PLATFORM_TITLE="Ubuntu, x86-64" ;;
    *) echo "unknown platform $SCANT_PLATFORM" >&2; exit 1 ;;
esac

default_prefix() {
    if [ "$SCANT_OS" = macos ]; then echo "$HOME/Library/scAnt"; else echo "${XDG_DATA_HOME:-$HOME/.local/share}/scAnt"; fi
}

PREFIX=""
WANT_FLIR=auto; WANT_COLMAP=yes; WANT_BRUSH=yes
FLIR_PKG=""; FLIR_SDK=""; FLIR_PY=""; COLMAP_VARIANT=auto
ACCEPT_FLIR=no; YES=no; LAUNCHER=yes; REPAIR=no; SYSTEM_SETUP=ask
while [ $# -gt 0 ]; do
    case "$1" in
        --prefix) PREFIX="${2:?--prefix needs a folder}"; shift ;;
        --prefix=*) PREFIX="${1#*=}" ;;
        --components|--components=*)
            if [ "$1" = --components ]; then list="${2:-}"; shift; else list="${1#*=}"; fi
            WANT_FLIR=no; WANT_COLMAP=no; WANT_BRUSH=no
            for c in $(echo "$list" | tr ',' ' '); do
                case "$c" in
                    core) ;;
                    flir) WANT_FLIR=yes ;;
                    colmap) WANT_COLMAP=yes ;;
                    brush) WANT_BRUSH=yes ;;
                    *) echo "unknown component '$c' (core, flir, colmap, brush)" >&2; exit 2 ;;
                esac
            done ;;
        --no-flir) WANT_FLIR=no ;;
        --no-colmap) WANT_COLMAP=no ;;
        --no-brush) WANT_BRUSH=no ;;
        --flir-pkg) FLIR_PKG="${2:?}"; shift ;;
        --flir-pkg=*) FLIR_PKG="${1#*=}" ;;
        --flir-sdk) FLIR_SDK="${2:?}"; shift ;;
        --flir-sdk=*) FLIR_SDK="${1#*=}" ;;
        --flir-python) FLIR_PY="${2:?}"; shift ;;
        --flir-python=*) FLIR_PY="${1#*=}" ;;
        --colmap) COLMAP_VARIANT="${2:?}"; shift ;;
        --colmap=*) COLMAP_VARIANT="${1#*=}" ;;
        --accept-flir-license) ACCEPT_FLIR=yes ;;
        --yes|-y) YES=yes ;;
        --no-launcher) LAUNCHER=no ;;
        --repair) REPAIR=yes ;;
        --system-setup) SYSTEM_SETUP=yes ;;
        --no-system-setup) SYSTEM_SETUP=no ;;
        --uninstall) echo "Run uninstall.sh in the install folder ($(default_prefix)/uninstall.sh)." >&2; exit 2 ;;
        -h|--help) usage; exit 0 ;;
        *) echo "unknown option $1 (--help lists them)" >&2; exit 2 ;;
    esac
    shift
done
case "$COLMAP_VARIANT" in cpu|cuda|auto) ;; *) echo "--colmap takes cpu, cuda or auto" >&2; exit 2 ;; esac
[ -n "$PREFIX" ] || PREFIX="$(default_prefix)"
case "$PREFIX" in /*) ;; *) PREFIX="$(pwd -P)/$PREFIX" ;; esac
PREFIX="${PREFIX%/}"

# ---------------------------------------------------------------------------------------------------------------
# helpers
# ---------------------------------------------------------------------------------------------------------------

INTERACTIVE=no
if [ "$YES" = no ] && [ -t 0 ] && [ -t 1 ]; then INTERACTIVE=yes; fi
LOGFILE=""
say() { echo "$*"; if [ -n "$LOGFILE" ]; then echo "$*" >> "$LOGFILE"; fi; }
step() { say ""; say "==> $*"; }
warn() { say "WARNING: $*"; }
die() { say ""; say "ERROR: $*"; if [ -n "$LOGFILE" ]; then say "The log is $LOGFILE"; fi; exit 1; }
# run CMD...: its output goes to the log only (the console shows the step); fails the install on error
run() { if [ -n "$LOGFILE" ]; then echo "+ $*" >> "$LOGFILE"; "$@" >> "$LOGFILE" 2>&1; else "$@"; fi; }
ask() { # ask "question" default(y|n) -> 0 for yes
    local answer
    if [ "$INTERACTIVE" = no ]; then [ "$2" = y ]; return; fi
    if [ "$2" = y ]; then printf '%s [Y/n] ' "$1"; else printf '%s [y/N] ' "$1"; fi
    read -r answer || answer=""
    case "$answer" in [Yy]*) return 0 ;; [Nn]*) return 1 ;; *) [ "$2" = y ] ;; esac
}
sha256_of() { if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d' ' -f1; else shasum -a 256 "$1" | cut -d' ' -f1; fi; }
verify() { # verify FILE SHA256 WHAT
    local got; got=$(sha256_of "$1")
    [ "$got" = "$2" ] || die "$3: SHA-256 $got, expected $2 ($1)"
}
download() { # download URL SHA256 DEST WHAT; keeps verified files in payload-cache/downloads
    local url="$1" sha="$2" dest="$3" what="$4" attempt
    if [ -f "$dest" ] && [ "$(sha256_of "$dest")" = "$sha" ]; then say "    $what: already downloaded"; return; fi
    say "    downloading $what"
    for attempt in 1 2 3; do
        if curl -fL --retry 5 --retry-delay 5 --connect-timeout 30 -sS -o "$dest.part" "$url" >> "$LOGFILE" 2>&1; then
            if [ "$(sha256_of "$dest.part")" = "$sha" ]; then mv -f "$dest.part" "$dest"; return; fi
            say "    $what: checksum mismatch (attempt $attempt)"
        else
            say "    $what: download failed (attempt $attempt)"
        fi
        rm -f "$dest.part"; sleep 5
    done
    die "$what could not be downloaded from $url"
}
mamba() { # mamba create PREFIX LOCK
    local attempt
    for attempt in 1 2 3; do
        if run env MAMBA_ROOT_PREFIX="$CACHE/mamba" CONDA_PKGS_DIRS="$CACHE/pkgs" MAMBA_NO_BANNER=1 \
                "$MM" create -y --no-rc -p "$1" --file "$2"; then return 0; fi
        say "    environment creation failed (attempt $attempt); retrying"
        rm -rf "$1"; sleep 10
    done
    return 1
}
pip_install() { run "$PREFIX/env/bin/python" -I -m pip install --isolated --no-deps --no-cache-dir \
                    --disable-pip-version-check --no-input --no-warn-script-location "$@"; }

# ---------------------------------------------------------------------------------------------------------------
# preflight
# ---------------------------------------------------------------------------------------------------------------

echo ""
echo "scAnt Setup $SCANT_VERSION ($SCANT_PLATFORM_TITLE)"
echo "app tree $APP_TREE_SHA, payload set $PAYLOAD_SET"

[ "$(id -u)" != 0 ] || { echo "ERROR: run scAnt Setup as your own user, not as root or with sudo." >&2; exit 1; }
case "$PREFIX" in *" "*) echo "ERROR: the install folder must not contain spaces: $PREFIX" >&2; exit 1 ;; esac
command -v curl >/dev/null 2>&1 || { echo "ERROR: curl is needed (Ubuntu: sudo apt install curl)" >&2; exit 1; }

MACOS_MAJOR=0
if [ "$SCANT_OS" = macos ]; then
    [ "$(uname -s)" = Darwin ] || { echo "ERROR: this is the macOS installer" >&2; exit 1; }
    [ "$(uname -m)" = arm64 ] || { echo "ERROR: scAnt for macOS needs an Apple Silicon Mac (arm64)" >&2; exit 1; }
    MACOS_MAJOR=$(sw_vers -productVersion | cut -d. -f1)
    [ "$MACOS_MAJOR" -ge 14 ] || { echo "ERROR: scAnt needs macOS 14 or later (this is $(sw_vers -productVersion))" >&2; exit 1; }
else
    [ "$(uname -s)" = Linux ] || { echo "ERROR: this is the Ubuntu installer" >&2; exit 1; }
    [ "$(uname -m)" = x86_64 ] || { echo "ERROR: scAnt for Ubuntu needs an x86-64 computer" >&2; exit 1; }
    UBUNTU_CODENAME=""
    if [ -r /etc/os-release ]; then UBUNTU_CODENAME=$(. /etc/os-release; echo "${VERSION_CODENAME:-}"); fi
    case "$UBUNTU_CODENAME" in
        jammy|noble) ;;
        *) echo "WARNING: scAnt is made for Ubuntu 22.04 (jammy) and 24.04 (noble); this is '${UBUNTU_CODENAME:-unknown}'." ;;
    esac
    GLIBC=$(getconf GNU_LIBC_VERSION 2>/dev/null | awk '{print $2}')
    case "$GLIBC" in 2.[0-9]|2.[12][0-9]|2.3[0-4]) echo "ERROR: glibc $GLIBC is too old (2.35 or later, Ubuntu 22.04+)" >&2; exit 1 ;; esac
fi

mkdir -p "$PREFIX" || { echo "ERROR: cannot create $PREFIX" >&2; exit 1; }
LOGFILE="$PREFIX/install.log"
{ echo ""; echo "=== scAnt Setup $SCANT_VERSION $SCANT_PLATFORM, $(date '+%Y-%m-%d %H:%M:%S'), prefix $PREFIX"; } >> "$LOGFILE"
CACHE="$PREFIX/payload-cache"
mkdir -p "$CACHE/downloads" "$PREFIX/bin" "$PREFIX/third_party_licenses"
MM="$PREFIX/payload-cache/env-lock/micromamba"

if pgrep -f "$PREFIX/env/bin/python" >/dev/null 2>&1; then
    die "scAnt is running from $PREFIX: quit it first"
fi
avail_kb=$(df -Pk "$PREFIX" | awk 'NR==2 {print $4}')
if [ "${avail_kb:-0}" -lt $((8 * 1024 * 1024)) ]; then
    warn "less than 8 GB free in $PREFIX ($((avail_kb / 1024 / 1024)) GB); a full install needs about 5 GB (Ubuntu with CUDA COLMAP about 8)"
fi

# ---------------------------------------------------------------------------------------------------------------
# what to install
# ---------------------------------------------------------------------------------------------------------------

find_first() { local f; for f in "$@"; do if [ -f "$f" ]; then echo "$f"; return; fi; done; }
if [ "$SCANT_OS" = macos ]; then
    if [ "$WANT_FLIR" != no ] && [ -z "$FLIR_PKG" ]; then
        FLIR_PKG=$(find_first "$HOME/Downloads/$FLIR_PKG_NAME" "$HOME/Downloads/${FLIR_PKG_NAME%.pkg}.dmg" "$HOME/Desktop/$FLIR_PKG_NAME")
        if [ -z "$FLIR_PKG" ] && [ "$INTERACTIVE" = yes ] && ask "Install FLIR camera support? It needs Teledyne's $FLIR_PKG_NAME (or its .dmg)." y; then
            printf 'Path to %s or its .dmg (drag it into this window): ' "$FLIR_PKG_NAME"
            read -r FLIR_PKG || FLIR_PKG=""
            FLIR_PKG=$(echo "$FLIR_PKG" | sed -e "s/^[\"']//" -e "s/[\"']\$//" -e 's/\\ / /g' -e 's/ *$//')
        fi
    fi
    if [ "$WANT_FLIR" = auto ]; then if [ -n "$FLIR_PKG" ]; then WANT_FLIR=yes; else WANT_FLIR=no; fi; fi
    if [ "$WANT_FLIR" = yes ] && [ ! -f "$FLIR_PKG" ]; then die "FLIR support needs Teledyne's $FLIR_PKG_NAME: pass it with --flir-pkg FILE"; fi
    if [ "$WANT_COLMAP" = yes ] && [ "$MACOS_MAJOR" -lt 15 ]; then
        warn "COLMAP $COLMAP_VERSION needs macOS 15 or later: COLMAP (and so Gaussian splatting) is left out"
        WANT_COLMAP=no
    fi
else
    if [ "$WANT_FLIR" != no ] && [ -z "$FLIR_PY" ]; then
        FLIR_PY=$(find_first "$HOME/Downloads/$FLIR_PY_NAME")
    fi
    if [ "$WANT_FLIR" != no ] && [ -z "$FLIR_SDK" ]; then
        case "${UBUNTU_CODENAME:-}" in
            jammy) FLIR_SDK=$(find_first "$HOME/Downloads/$FLIR_SDK_JAMMY_NAME") ;;
            noble) FLIR_SDK=$(find_first "$HOME/Downloads/$FLIR_SDK_NOBLE_NAME") ;;
        esac
    fi
    if [ "$WANT_FLIR" = auto ]; then
        if [ -n "$FLIR_PY" ]; then WANT_FLIR=yes
        elif [ "$INTERACTIVE" = yes ] && ask "Install FLIR camera support? It needs Teledyne's $FLIR_PY_NAME (and the Spinnaker SDK for Ubuntu)." y; then
            printf 'Path to %s: ' "$FLIR_PY_NAME"; read -r FLIR_PY || FLIR_PY=""
            FLIR_PY=$(echo "$FLIR_PY" | sed -e "s/^[\"']//" -e "s/[\"']\$//" -e 's/ *$//')
            WANT_FLIR=yes
        else WANT_FLIR=no; fi
    fi
    if [ "$WANT_FLIR" = yes ] && [ ! -f "$FLIR_PY" ]; then die "FLIR support needs Teledyne's $FLIR_PY_NAME: pass it with --flir-python FILE"; fi
    if [ "$WANT_COLMAP" = yes ] && [ "$COLMAP_VARIANT" = auto ]; then
        COLMAP_VARIANT=cpu
        if command -v nvidia-smi >/dev/null 2>&1; then
            gpu=$(nvidia-smi --query-gpu=compute_cap,driver_version --format=csv,noheader 2>/dev/null | head -1 || true)
            cc=$(echo "$gpu" | cut -d, -f1 | tr -d ' '); drv=$(echo "$gpu" | cut -d, -f2 | tr -d ' ' | cut -d. -f1)
            ccmaj=${cc%%.*}; ccmin=${cc#*.}
            if [ -n "$drv" ] && [ "$drv" -ge "$COLMAP_CUDA_MIN_DRIVER" ] 2>/dev/null \
               && { [ "${ccmaj:-0}" -gt 7 ] || { [ "${ccmaj:-0}" -eq 7 ] && [ "${ccmin:-0}" -ge 5 ]; }; } 2>/dev/null; then
                COLMAP_VARIANT=cuda
            else
                say "NVIDIA GPU found (compute capability ${cc:-?}, driver ${drv:-?}): the CUDA build of COLMAP needs compute capability 7.5+ and driver $COLMAP_CUDA_MIN_DRIVER+, so the CPU build is used"
            fi
        fi
    fi
fi

say ""
say "Install folder: $PREFIX"
say "Components:     core$( [ "$WANT_FLIR" = yes ] && echo ", FLIR camera support")$( [ "$WANT_COLMAP" = yes ] && echo ", COLMAP $COLMAP_VERSION$( [ "$SCANT_OS" = linux ] && echo " ($COLMAP_VARIANT)")")$( [ "$WANT_BRUSH" = yes ] && echo ", Brush $BRUSH_VERSION")"
if [ "$INTERACTIVE" = yes ] && ! ask "Continue?" y; then echo "Nothing was installed."; exit 0; fi

# ---------------------------------------------------------------------------------------------------------------
# the FLIR licence first, so that a refusal changes nothing
# ---------------------------------------------------------------------------------------------------------------

FLIR_WORK=""
cleanup() {
    if [ -n "$FLIR_WORK" ]; then
        if [ -n "${FLIR_DMG_MOUNT:-}" ]; then hdiutil detach -quiet "$FLIR_DMG_MOUNT" 2>/dev/null || true; fi
        rm -rf "$FLIR_WORK"
    fi
}
trap cleanup EXIT

accept_flir_license() { # accept_flir_license LICENSE_FILE
    [ -f "$1" ] || die "the FLIR licence text is missing from Teledyne's files ($1)"
    if [ "$ACCEPT_FLIR" = yes ]; then say "    FLIR Spinnaker SDK License Agreement accepted (--accept-flir-license)"; return; fi
    [ "$INTERACTIVE" = yes ] || die "FLIR support needs the FLIR Spinnaker SDK License Agreement accepted: run interactively, or pass --accept-flir-license"
    echo ""
    echo "The FLIR camera support contains proprietary Teledyne FLIR software. It is governed by the FLIR"
    echo "Spinnaker SDK License Agreement (use only with FLIR cameras; no further redistribution). Read it now"
    echo "(q leaves the viewer)."
    printf 'Press Return to show it. '; read -r _ || true
    if command -v less >/dev/null 2>&1; then less -e "$1" || true; else cat "$1"; fi
    printf 'Type "accept" to accept the FLIR Spinnaker SDK License Agreement (anything else skips FLIR support): '
    local answer; read -r answer || answer=""
    if [ "$answer" != accept ]; then say "    licence not accepted: FLIR camera support is left out"; WANT_FLIR=no; return; fi
    say "    FLIR Spinnaker SDK License Agreement accepted"
}

if [ "$WANT_FLIR" = yes ]; then
    step "FLIR camera support: checking Teledyne's files"
    FLIR_WORK=$(mktemp -d "${TMPDIR:-/tmp}/scant-flir.XXXXXX")
    if [ "$SCANT_OS" = macos ]; then
        case "$FLIR_PKG" in
            *.dmg)
                FLIR_DMG_MOUNT="$FLIR_WORK/dmg"; mkdir -p "$FLIR_DMG_MOUNT"
                run hdiutil attach -nobrowse -readonly -noautoopen -mountpoint "$FLIR_DMG_MOUNT" "$FLIR_PKG" \
                    || die "cannot open $FLIR_PKG"
                FLIR_PKG=$(find "$FLIR_DMG_MOUNT" -maxdepth 2 -name "$FLIR_PKG_NAME" | head -1)
                [ -n "$FLIR_PKG" ] || die "the disk image holds no $FLIR_PKG_NAME" ;;
        esac
        verify "$FLIR_PKG" "$FLIR_PKG_SHA256" "$FLIR_PKG_NAME (only this Spinnaker version is supported)"
        run pkgutil --expand-full "$FLIR_PKG" "$FLIR_WORK/pkg" || die "cannot unpack $FLIR_PKG"
        accept_flir_license "$FLIR_WORK/pkg/Resources/License.txt"
    else
        verify "$FLIR_PY" "$FLIR_PY_SHA256" "$FLIR_PY_NAME (only this Spinnaker version is supported)"
        mkdir -p "$FLIR_WORK/py"
        run tar -xzf "$FLIR_PY" -C "$FLIR_WORK/py" --exclude docs --exclude Examples || die "cannot unpack $FLIR_PY"
        accept_flir_license "$FLIR_WORK/py/licenses/FLIR_license.txt"
    fi
fi

# ---------------------------------------------------------------------------------------------------------------
# core: app tree, Python environment, stacking tools
# ---------------------------------------------------------------------------------------------------------------

step "Installing the scAnt app ($SCANT_VERSION)"
mkdir -p "$PREFIX/app"
(cd "$SRC/app" && find . \( -type f -o -type l \) | sed 's|^\./||' | LC_ALL=C sort) > "$PREFIX/app-files.txt"
(cd "$SRC/app" && tar -cf - .) | (cd "$PREFIX/app" && tar -xf -)
rm -rf "$CACHE/env-lock"; cp -R "$SRC/payloads/env-lock" "$CACHE/env-lock"; chmod +x "$MM"
cp -R "$SRC/third_party/." "$PREFIX/third_party_licenses/"

LOCK_SUM=$(cat "$CACHE/env-lock/$ENV_LOCK" "$CACHE/env-lock/$ENV_REQUIREMENTS" "$SRC/payloads/shinestacker/wheel/$SHINESTACKER_WHEEL" \
           | { if command -v sha256sum >/dev/null 2>&1; then sha256sum; else shasum -a 256; fi; } | cut -d' ' -f1)
if [ "$REPAIR" = no ] && [ -x "$PREFIX/env/bin/python" ] && [ "$(cat "$PREFIX/env/.scant-env-sum" 2>/dev/null)" = "$LOCK_SUM" ]; then
    step "Python environment: up to date"
else
    step "Creating the Python environment (downloads about 350-550 MB from conda-forge and PyPI; several minutes)"
    rm -rf "$PREFIX/env"
    mamba "$PREFIX/env" "$CACHE/env-lock/$ENV_LOCK" || die "the Python environment could not be created (network?)"
    say "    pip packages (hash-pinned)"
    pip_install --require-hashes --no-build-isolation -r "$CACHE/env-lock/$ENV_REQUIREMENTS" \
        || die "the pinned pip packages could not be installed"
    say "    shinestacker $SHINESTACKER_VERSION"
    pip_install --no-index "$SRC/payloads/shinestacker/wheel/$SHINESTACKER_WHEEL" || die "shinestacker could not be installed"
    echo "$LOCK_SUM" > "$PREFIX/env/.scant-env-sum"
fi

step "Stacking tools"
FS_DIR="$PREFIX/app/external/focus-stack"
rm -rf "$FS_DIR"; mkdir -p "$FS_DIR"
if [ "$SCANT_OS" = macos ]; then
    ditto --noqtn "$SRC/payloads/focus-stack/focus-stack.app" "$FS_DIR/focus-stack.app"
    xattr -dr com.apple.quarantine "$FS_DIR/focus-stack.app" 2>/dev/null || true
    FOCUS_STACK_BIN="$FS_DIR/focus-stack.app/Contents/MacOS/focus-stack"
else
    # extracted once, so it runs without FUSE (libfuse2 is not on every Ubuntu); scAnt starts
    # external/focus-stack/focus-stack.AppImage, here a script that runs the extracted program
    cp "$SRC/payloads/focus-stack/focus-stack.AppImage" "$CACHE/focus-stack.AppImage"; chmod +x "$CACHE/focus-stack.AppImage"
    (cd "$FS_DIR" && "$CACHE/focus-stack.AppImage" --appimage-extract > /dev/null) || die "the focus-stack AppImage could not be extracted"
    printf '#!/bin/sh\nexec "$(dirname "$0")/squashfs-root/AppRun" "$@"\n' > "$FS_DIR/focus-stack.AppImage"
    chmod +x "$FS_DIR/focus-stack.AppImage"
    FOCUS_STACK_BIN="$FS_DIR/focus-stack.AppImage"
fi
cp "$SRC/payloads/focus-stack/LICENSE.md" "$FS_DIR/LICENSE.md"

# ---------------------------------------------------------------------------------------------------------------
# optional components
# ---------------------------------------------------------------------------------------------------------------

COLMAP_BIN=""; BRUSH_BIN=""
if [ "$WANT_COLMAP" = yes ]; then
    step "COLMAP $COLMAP_VERSION"
    C_DIR="$PREFIX/app/SPLAT/external/colmap"
    if [ "$SCANT_OS" = macos ]; then
        download "$COLMAP_URL" "$COLMAP_SHA256" "$CACHE/downloads/$(basename "$COLMAP_URL")" "COLMAP $COLMAP_VERSION (upstream, $COLMAP_SIZE_MB MB)"
        t=$(mktemp -d "${TMPDIR:-/tmp}/scant-colmap.XXXXXX")
        ditto -x -k --noqtn "$CACHE/downloads/$(basename "$COLMAP_URL")" "$t"
        ditto -x -k --noqtn "$t/COLMAP-mac.zip" "$t"
        rm -rf "$C_DIR"; mkdir -p "$C_DIR"
        ditto --noqtn "$t/COLMAP.app" "$C_DIR/COLMAP.app"; rm -rf "$t"
        xattr -dr com.apple.quarantine "$C_DIR/COLMAP.app" 2>/dev/null || true
        COLMAP_BIN="$C_DIR/COLMAP.app/Contents/MacOS/colmap"
    else
        lock="$COLMAP_CPU_LOCK"; [ "$COLMAP_VARIANT" = cuda ] && lock="$COLMAP_CUDA_LOCK"
        sum=$(sha256_of "$CACHE/env-lock/$lock")
        if [ "$REPAIR" = no ] && [ -x "$PREFIX/tools/colmap/bin/colmap" ] && [ "$(cat "$PREFIX/tools/colmap/.scant-env-sum" 2>/dev/null)" = "$sum" ]; then
            say "    COLMAP environment: up to date"
        else
            say "    conda-forge COLMAP ($COLMAP_VARIANT build; $( [ "$COLMAP_VARIANT" = cuda ] && echo "about 1.6 GB" || echo "about 380 MB") of downloads)"
            rm -rf "$PREFIX/tools/colmap"; mkdir -p "$PREFIX/tools"
            mamba "$PREFIX/tools/colmap" "$CACHE/env-lock/$lock" || die "COLMAP could not be installed (network?)"
            echo "$sum" > "$PREFIX/tools/colmap/.scant-env-sum"
        fi
        # scAnt 1.0.0 looks for SPLAT/external/colmap/bin/colmap.exe on Linux too
        rm -rf "$C_DIR"; mkdir -p "$C_DIR/bin"
        ln -s "$PREFIX/tools/colmap/bin/colmap" "$C_DIR/bin/colmap.exe"
        COLMAP_BIN="$C_DIR/bin/colmap.exe"
    fi
fi

if [ "$WANT_BRUSH" = yes ]; then
    step "Brush $BRUSH_VERSION"
    B_DIR="$PREFIX/app/SPLAT/external/brush"
    download "$BRUSH_URL" "$BRUSH_SHA256" "$CACHE/downloads/$(basename "$BRUSH_URL")" "Brush $BRUSH_VERSION (upstream, $BRUSH_SIZE_MB MB)"
    t=$(mktemp -d "${TMPDIR:-/tmp}/scant-brush.XXXXXX")
    tar -xJf "$CACHE/downloads/$(basename "$BRUSH_URL")" -C "$t"
    rm -rf "$B_DIR"; mkdir -p "$B_DIR"
    cp "$t"/brush-app-*/brush_app "$t"/brush-app-*/LICENSE "$t"/brush-app-*/README.md "$t"/brush-app-*/CHANGELOG.md "$B_DIR/"
    rm -rf "$t"; chmod +x "$B_DIR/brush_app"
    BRUSH_BIN="$B_DIR/brush_app"
    if [ "$SCANT_OS" = linux ]; then ln -s brush_app "$B_DIR/brush_app.exe"; fi  # the name scAnt 1.0.0 uses on Linux
fi

FLIR_RUNTIME=""
if [ "$WANT_FLIR" = yes ]; then
    step "FLIR camera support (Spinnaker $FLIR_VERSION)"
    if [ "$SCANT_OS" = macos ]; then
        # Teledyne's libraries, unmodified, in a folder of their own; the launcher points
        # DYLD_FALLBACK_LIBRARY_PATH (or DYLD_LIBRARY_PATH, see bin/scant-env) at it. ffmpeg 6 for libSpinVideo is
        # scAnt's LGPL build; libomp and libusb are the env's, so the process holds one OpenMP runtime.
        FLIR_RUNTIME="$PREFIX/flir/lib"
        rm -rf "$PREFIX/flir"; mkdir -p "$FLIR_RUNTIME/spinnaker-gentl" "$PREFIX/flir/licenses"
        libs=$(ls -d "$FLIR_WORK"/pkg/Spinnaker-*-libraries.pkg 2>/dev/null | head -1 || true)
        gentl=$(ls -d "$FLIR_WORK"/pkg/Spinnaker-*-gentl.pkg 2>/dev/null | head -1 || true)
        pyspin=$(ls -d "$FLIR_WORK"/pkg/Spinnaker-*-pyspin-310.pkg 2>/dev/null | head -1 || true)
        [ -n "$libs" ] && [ -n "$gentl" ] && [ -n "$pyspin" ] || die "$FLIR_PKG_NAME lacks the libraries, GenTL or PySpin 3.10 component"
        for f in "$libs"/Payload/usr/local/lib/*.dylib; do
            case "$(basename "$f")" in libCppUnit_*|libGCBaseTest_*) continue ;; esac
            cp -a "$f" "$FLIR_RUNTIME/"
        done
        cp -a "$gentl/Payload/usr/local/lib/spinnaker-gentl/Spinnaker_GenTL.cti" "$FLIR_RUNTIME/spinnaker-gentl/"
        cp -a "$SRC/payloads/ffmpeg-spinvideo/lib/." "$FLIR_RUNTIME/"
        ln -s ../../env/lib/libomp.dylib "$FLIR_RUNTIME/libomp.dylib"
        ln -s ../../env/lib/libusb-1.0.0.dylib "$FLIR_RUNTIME/libusb-1.0.0.dylib"
        xattr -dr com.apple.quarantine "$PREFIX/flir" 2>/dev/null || true
        tarball=$(ls "$pyspin"/Payload/Applications/Spinnaker/PySpin/spinnaker_python-*-cp310-*.tar.gz | head -1)
        mkdir -p "$FLIR_WORK/py"; tar -xzf "$tarball" -C "$FLIR_WORK/py"
        wheel=$(ls "$FLIR_WORK"/py/spinnaker_python-*-cp310-*.whl | head -1)
        cp "$FLIR_WORK/pkg/Resources/License.txt" "$PREFIX/flir/licenses/FLIR_license.txt"
        cp "$libs"/Payload/Applications/Spinnaker/licenses/* "$PREFIX/flir/licenses/" 2>/dev/null || true
    else
        wheel=$(ls "$FLIR_WORK"/py/spinnaker_python-*-cp310-*.whl | head -1)
        mkdir -p "$PREFIX/flir/licenses"; cp "$FLIR_WORK"/py/licenses/* "$PREFIX/flir/licenses/"
    fi
    say "    PySpin $FLIR_VERSION"
    pip_install --no-index --force-reinstall "$wheel" || die "PySpin could not be installed"
    # opt out of the analytics in Teledyne's library, unless the user has decided already
    if [ ! -e "$HOME/.config/spinnaker/privacy.xml" ]; then
        mkdir -p "$HOME/.config/spinnaker/logs"
        printf '<?xml version="1.0" encoding="utf-8"?>\n<PrivacyConfig>\n  <Disabled>true</Disabled>\n</PrivacyConfig>\n' \
            > "$HOME/.config/spinnaker/privacy.xml"
        echo "$HOME/.config/spinnaker/privacy.xml" > "$PREFIX/flir/created-privacy-xml"
        say "    Spinnaker analytics switched off (~/.config/spinnaker/privacy.xml)"
    fi
fi

# ---------------------------------------------------------------------------------------------------------------
# Ubuntu: what needs sudo
# ---------------------------------------------------------------------------------------------------------------

if [ "$SCANT_OS" = linux ]; then
    SUDO_STEPS=""
    id -nG 2>/dev/null | tr ' ' '\n' | grep -qx dialout || SUDO_STEPS="${SUDO_STEPS}dialout "
    [ -f /etc/udev/rules.d/99-scant-controller.rules ] || SUDO_STEPS="${SUDO_STEPS}modemmanager "
    sdk_have=$(dpkg-query -W -f='${Version}' libspinnaker 2>/dev/null || true)
    if [ "$WANT_FLIR" = yes ] && [ "$sdk_have" != "$FLIR_VERSION" ]; then SUDO_STEPS="${SUDO_STEPS}flir-sdk "; fi
    if [ -n "$SUDO_STEPS" ]; then
        step "System setup (needs sudo)"
        case " $SUDO_STEPS " in *" dialout "*) say "  - add $(id -un) to the group dialout (the scanner controller's serial port)" ;; esac
        case " $SUDO_STEPS " in *" modemmanager "*) say "  - /etc/udev/rules.d/99-scant-controller.rules: ModemManager leaves the controller (USB 1d50:6029) alone" ;; esac
        case " $SUDO_STEPS " in *" flir-sdk "*)
            say "  - FLIR: the libraries Spinnaker needs (libusb, ffmpeg) from Ubuntu, then Teledyne's own"
            say "    install_spinnaker.sh from $FLIR_SDK_JAMMY_NAME / $FLIR_SDK_NOBLE_NAME"
            say "    (answer its questions: yes to the udev entry and to the 1000 MB USB-FS memory)"
            if [ -n "$sdk_have" ]; then say "    Spinnaker $sdk_have is installed: Teledyne's installer stops until it is removed (sudo sh remove_spinnaker.sh)"; fi ;;
        esac
        do_it=no
        if [ "$SYSTEM_SETUP" = yes ]; then do_it=yes
        elif [ "$SYSTEM_SETUP" = ask ] && [ "$INTERACTIVE" = yes ] && ask "Run these steps now with sudo?" y; then do_it=yes; fi
        if [ "$do_it" = yes ]; then
            case " $SUDO_STEPS " in *" dialout "*) sudo usermod -aG dialout "$(id -un)" && say "    added to dialout: log out and in again" ;; esac
            case " $SUDO_STEPS " in *" modemmanager "*)
                printf '%s\n' '# scAnt: ModemManager must not probe the scanner controller (it would disturb the serial port)' \
                    'ATTRS{idVendor}=="1d50", ATTRS{idProduct}=="6029", ENV{ID_MM_DEVICE_IGNORE}="1"' \
                    | sudo tee /etc/udev/rules.d/99-scant-controller.rules > /dev/null
                sudo udevadm control --reload-rules 2>/dev/null || true
                say "    ModemManager rule written" ;;
            esac
            case " $SUDO_STEPS " in *" flir-sdk "*)
                case "${UBUNTU_CODENAME:-}" in
                    jammy) deps="libusb-1.0-0 libavcodec58 libavformat58 libswscale5 libswresample3 libavutil56"; want_sdk="$FLIR_SDK_JAMMY_NAME"; want_sum="$FLIR_SDK_JAMMY_SHA256" ;;
                    noble) deps="libusb-1.0-0 libavcodec60 libavformat60 libswscale7 libswresample4 libavutil58"; want_sdk="$FLIR_SDK_NOBLE_NAME"; want_sum="$FLIR_SDK_NOBLE_SHA256" ;;
                    *) die "Teledyne's Spinnaker $FLIR_VERSION is made for Ubuntu 22.04 and 24.04; install it by hand, then re-run scAnt Setup" ;;
                esac
                [ -n "$FLIR_SDK" ] && [ -f "$FLIR_SDK" ] || die "the Spinnaker SDK is not installed: pass Teledyne's $want_sdk with --flir-sdk FILE"
                verify "$FLIR_SDK" "$want_sum" "$want_sdk"
                # shellcheck disable=SC2086
                sudo apt-get update -q || true
                sudo apt-get install -y $deps
                mkdir -p "$FLIR_WORK/sdk"; tar -xzf "$FLIR_SDK" -C "$FLIR_WORK/sdk"
                sdkdir=$(ls -d "$FLIR_WORK"/sdk/spinnaker-* | head -1)
                # Teledyne's packages ask their questions (licence, analytics) through debconf, and their preinst
                # stops when it cannot show one: this step needs a terminal
                [ -t 0 ] || die "Teledyne's Spinnaker installer asks its questions in a terminal: run this step from a terminal (re-run scAnt Setup with --system-setup)"
                if [ "$ACCEPT_FLIR" = yes ]; then
                    # accepted with --accept-flir-license: Teledyne's packages get the same answer for the licence
                    echo 'libspinnaker libspinnaker/accepted-flir-eula boolean true' | sudo debconf-set-selections
                fi
                (cd "$sdkdir" && bash ./install_spinnaker.sh) || die "Teledyne's install_spinnaker.sh failed"
                [ "$(dpkg-query -W -f='${Version}' libspinnaker 2>/dev/null || true)" = "$FLIR_VERSION" ] || die "Spinnaker $FLIR_VERSION is not installed after Teledyne's installer"
                say "    Spinnaker $FLIR_VERSION installed (reboot before using the camera)" ;;
            esac
        else
            say "  Not run. To do it later: re-run this installer with --system-setup, or follow docs in"
            say "  $PREFIX/app/README.md (Ubuntu). FLIR cameras and the controller need these steps."
            if [ "$WANT_FLIR" = yes ] && [ "$sdk_have" != "$FLIR_VERSION" ]; then
                warn "PySpin is installed, but the Spinnaker $FLIR_VERSION SDK is not: the camera will not work until it is"
            fi
        fi
    fi
fi

# ---------------------------------------------------------------------------------------------------------------
# launcher
# ---------------------------------------------------------------------------------------------------------------

step "Launcher"
{
    echo "# scAnt $SCANT_VERSION: the environment scAnt runs in (generated by scAnt Setup; sourced by bin/scant)"
    echo "SCANT_PREFIX=\"$PREFIX\""
    echo 'export PATH="$SCANT_PREFIX/env/bin:/usr/bin:/bin:/usr/sbin:/sbin${PATH:+:$PATH}"'
    echo 'export PYTHONUNBUFFERED=1 PYTHONNOUSERSITE=1'
    echo 'unset PYTHONPATH PYTHONHOME PYTHONSTARTUP CONDA_PREFIX'
    if [ -n "$FLIR_RUNTIME" ]; then
        cat <<EOF
# Teledyne's Spinnaker libraries (unmodified) are found through the fallback path, which only fills in libraries
# that are missing, so COLMAP, Brush and focus-stack keep their own. If Teledyne's or Homebrew's copies are on this
# Mac, they would win there, and the runtime folder is put first instead.
SCANT_FLIR_LIB="\$SCANT_PREFIX/flir/lib"
if [ -e /usr/local/lib/libSpinnaker.4.dylib ] || [ -e /opt/homebrew/opt/libomp/lib/libomp.dylib ] \\
   || [ -e /opt/homebrew/lib/libusb-1.0.0.dylib ] || [ -e /opt/homebrew/opt/ffmpeg@6/lib/libavcodec.60.dylib ] \\
   || [ -e /usr/local/opt/libomp/lib/libomp.dylib ]; then
    export DYLD_LIBRARY_PATH="\$SCANT_FLIR_LIB"
else
    export DYLD_FALLBACK_LIBRARY_PATH="\$SCANT_FLIR_LIB:/usr/local/lib:/usr/lib"
fi
EOF
    fi
} > "$PREFIX/bin/scant-env"
cat > "$PREFIX/bin/scant" <<'EOF'
#!/bin/bash
# scAnt: starts the GUI in its environment. bin/scant --log writes the console to the log file (used by the
# app launcher); bin/scant run CMD... runs a command in scAnt's environment (from the app folder).
here="$(cd "$(dirname "$0")" && pwd -P)"
. "$here/scant-env"
cd "$SCANT_PREFIX/app" || exit 1
if [ "${1:-}" = run ]; then shift; exec "$@"; fi
if [ "${1:-}" = --log ]; then
    shift
    if [ "$(uname -s)" = Darwin ]; then logdir="$HOME/Library/Logs/scAnt"; else logdir="${XDG_STATE_HOME:-$HOME/.local/state}/scAnt"; fi
    mkdir -p "$logdir"
    if [ -f "$logdir/scAnt.log" ] && [ "$(wc -c < "$logdir/scAnt.log")" -gt 20000000 ]; then mv -f "$logdir/scAnt.log" "$logdir/scAnt.log.1"; fi
    echo "=== scAnt started $(date '+%Y-%m-%d %H:%M:%S')" >> "$logdir/scAnt.log"
    exec "$SCANT_PREFIX/env/bin/python" scAnt.py "$@" >> "$logdir/scAnt.log" 2>&1
fi
exec "$SCANT_PREFIX/env/bin/python" scAnt.py "$@"
EOF
chmod +x "$PREFIX/bin/scant"

LAUNCHER_PATH=""
if [ "$LAUNCHER" = yes ]; then
    if [ "$SCANT_OS" = macos ]; then
        LAUNCHER_PATH="$HOME/Applications/scAnt.app"
        rm -rf "$LAUNCHER_PATH"; mkdir -p "$LAUNCHER_PATH/Contents/MacOS" "$LAUNCHER_PATH/Contents/Resources"
        sed -e "s|@VERSION@|$SCANT_VERSION|g" "$SRC/launcher/Info.plist" > "$LAUNCHER_PATH/Contents/Info.plist"
        cp "$SRC/launcher/scAnt.icns" "$LAUNCHER_PATH/Contents/Resources/scAnt.icns"
        printf '#!/bin/bash\n# scAnt %s, installed in %s\nexec "%s/bin/scant" --log\n' "$SCANT_VERSION" "$PREFIX" "$PREFIX" \
            > "$LAUNCHER_PATH/Contents/MacOS/scAnt"
        chmod +x "$LAUNCHER_PATH/Contents/MacOS/scAnt"
        run codesign --force --sign - --identifier com.scant3d.scant "$LAUNCHER_PATH" || warn "the app could not be signed ad hoc"
        say "    $LAUNCHER_PATH (open it from Finder, Launchpad or Spotlight)"
    else
        apps="${XDG_DATA_HOME:-$HOME/.local/share}/applications"
        icons="${XDG_DATA_HOME:-$HOME/.local/share}/icons/hicolor/256x256/apps"
        mkdir -p "$apps" "$icons"
        cp "$SRC/launcher/scant.png" "$icons/scant.png"
        LAUNCHER_PATH="$apps/scant.desktop"
        sed -e "s|@PREFIX@|$PREFIX|g" -e "s|@VERSION@|$SCANT_VERSION|g" "$SRC/launcher/scant.desktop" > "$LAUNCHER_PATH"
        chmod +x "$LAUNCHER_PATH"
        command -v update-desktop-database >/dev/null 2>&1 && update-desktop-database "$apps" >/dev/null 2>&1 || true
        say "    menu entry scAnt ($LAUNCHER_PATH); or start $PREFIX/bin/scant"
    fi
fi

# ---------------------------------------------------------------------------------------------------------------
# install record, uninstaller, checks
# ---------------------------------------------------------------------------------------------------------------

cat > "$PREFIX/install.json" <<EOF
{
 "product": "scAnt pro",
 "version": "$SCANT_VERSION",
 "platform": "$SCANT_PLATFORM",
 "app_tree": "$APP_TREE_SHA",
 "payload_set": "$PAYLOAD_SET",
 "installer_sha256_note": "the installer's own SHA-256 is in the release notes",
 "installed": "$(date '+%Y-%m-%dT%H:%M:%S%z')",
 "components": {"core": true, "flir": $( [ "$WANT_FLIR" = yes ] && echo true || echo false ), "colmap": $( [ "$WANT_COLMAP" = yes ] && echo "\"${COLMAP_VARIANT/auto/upstream}\"" || echo false ), "brush": $( [ "$WANT_BRUSH" = yes ] && echo true || echo false )},
 "launcher": "$LAUNCHER_PATH"
}
EOF
sed -e "s|@PREFIX@|$PREFIX|g" -e "s|@LAUNCHER@|$LAUNCHER_PATH|g" -e "s|@OS@|$SCANT_OS|g" "$SRC/uninstall.sh" > "$PREFIX/uninstall.sh"
chmod +x "$PREFIX/uninstall.sh"

sed -e "s|@FOCUS_STACK@|$FOCUS_STACK_BIN|g" -e "s|@COLMAP@|$COLMAP_BIN|g" -e "s|@BRUSH@|$BRUSH_BIN|g" \
    -e "s|@FLIR@|$WANT_FLIR|g" -e "s|@VERSION@|$SCANT_VERSION|g" "$SRC/check.sh" > "$PREFIX/bin/scant-check"
chmod +x "$PREFIX/bin/scant-check"

step "Checking the installation"
if "$PREFIX/bin/scant-check" > "$PREFIX/install-smoke.log" 2>&1; then
    sed 's/^/    /' "$PREFIX/install-smoke.log" | grep -E "^    (ok|FAIL)" | tee -a "$LOGFILE"
    say ""
    say "scAnt $SCANT_VERSION is installed in $PREFIX."
else
    sed 's/^/    /' "$PREFIX/install-smoke.log" | grep -E "^    (ok|FAIL)" | tee -a "$LOGFILE"
    say ""
    say "scAnt $SCANT_VERSION is installed in $PREFIX, but some checks failed: see $PREFIX/install-smoke.log"
    exit 3
fi
if [ "$SCANT_OS" = macos ]; then
    say "Start it with scAnt in ~/Applications (or $PREFIX/bin/scant from a terminal)."
    say "Quit scAnt from its window or with Cmd+Q: that switches the light off and releases the motors."
else
    say "Start it from the menu (scAnt) or with $PREFIX/bin/scant."
fi
say "Re-run this installer to add components or to repair; $PREFIX/uninstall.sh removes scAnt."
